mapper.select:
SELECT task.id AS dprId, customer.cid AS cid, customer.api_code AS apiCode, customer.short_name AS shortName, task.discreet_number AS discreetNumber, task.actual_number AS actualNumber, task.release_time_begin AS releaseTimeBegin, task.release_time_end AS releaseTimeEnd, task.task_type AS taskType, task.task_execute_time AS taskExecuteTime, task.task_status AS taskStatus, task.create_time AS createTime, task.update_time AS updateTime FROM b_xiecheng_colliding_data_process_task AS task JOIN b_marketing_customer AS customer ON task.api_code = customer.api_code WHERE task.is_delete = 0 AND ( (task.task_type = 1
AND task.release_time_begin >= #{releaseTimeBegin,jdbcType=TIMESTAMP} AND task.release_time_end <= #{releaseTimeEnd,jdbcType=TIMESTAMP} ) OR task.task_type = 3 )
AND task.task_type = #{taskType}
AND task.task_status = #{taskStatus}
ORDER BY createTime DESC, releaseTimeBegin DESC
